  2857	bool vmap_view_render_pump(vmap_view_t * view, unsigned max_tiles)
  2858	{
  2859	    unsigned n;
  2860	    uint32_t t0;
  2861	
  2862	    if (!view || !view->canvas || !view->cbuf || myvendor_mtp_lfs_quiesce()) {
  2863	        return true;
  2864	    }
  2865	
  2866	    if (view->pump_phase == 0) {
  2867	        /* 没有帧在飞 ⇒ 泵本来就不该被调用（帧结束后定时器自己暂停）。
  2868	         * **基准必须作废**，否则下一帧的第一拍会把"这一整段空闲"算成"UI 线程被占住"
  2869	         * —— 第一版就是这么误报的：`SLOW pump gap 9471ms` / `2228ms` 其实都是
  2870	         * "这段时间没渲染"（同期 BLE 每 10 秒的心跳照打，证明系统是活的）。 */
  2871	        s_pf_last_pump_cyc = 0u;
  2872	        return true;
  2873	    }
  2874	
  2875	    if (max_tiles == 0) {
  2876	        max_tiles = VMAP_RENDER_PUMP_MAX_TILES;
  2877	    }
  2878	
  2879	    t0 = lv_tick_get();
  2880	    myvendor_watchdog_ui_beat();
  2881	    /* 单拍间隔超长 ⇒ **无条件** WARNING（正常帧不受影响）。只在这一帧确实在飞时量，
  2882	     * 所以"没渲染的空闲"不会被算进来；而帧内一次 2 秒以上的拍间隔就只能是系统级
  2883	     * 停顿（现场两次 WDT 饥饿复位都伴随 1.6~12 秒的这类间隔，且当时 [vperf] 正被
  2884	     * 降到 debug、整场不可诊断）。 */
  2885	    {
  2886	        const uint32_t now_cyc = vmap_perf_cyc();
  2887	
  2888	        if (s_pf_last_pump_cyc != 0u && now_cyc - s_pf_last_pump_cyc
  2889	            > VMAP_PERF_SLOW_GAP_MS * 240u * 1000u) {
  2890	            syslog(LOG_WARNING,
  2891	                "[vperf] SLOW pump gap %ums (>%ums) —— 帧内拍间隔异常，UI 线程被占住；若同时 WDT 停喂即饥饿族",
  2892	                (unsigned)((now_cyc - s_pf_last_pump_cyc) / 240000u),
  2893	                (unsigned)VMAP_PERF_SLOW_GAP_MS);
  2894	            vmap_perf_dump_runnable();
  2895	        }
  2896	        s_pf_last_pump_cyc = now_cyc;
  2897	    }
  2898	
  2899	    for (n = 0; n < max_tiles && view->pump_phase != 0; n++) {
  2900	        if (n > 0 && lv_tick_elaps(t0) >= VMAP_RENDER_PUMP_BUDGET_MS) {
  2901	            break;
  2902	        }
  2903	        if (!render_next_tile(view)) {
  2904	            render_finish(view);
  2905	            break;
  2906	        }
  2907	        if (lv_tick_elaps(t0) >= VMAP_RENDER_PUMP_BUDGET_MS) {
  2908	            break;
  2909	        }
  2910	    }
  2911	
  2912	    return view->pump_phase == 0;
  2913	}
